mapper.select:
SELECT  

  JOIN tc_order anchor ON anchor.tenant_id=#{tenant} AND anchor.id=#{q.after}

WHERE r.tenant_id=#{tenant}



      AND (r.created_at < anchor.created_at OR (r.created_at=anchor.created_at AND r.id < anchor.id))


  AND r.id > #{q.after}

AND r.order_no=#{q.filters.orderNo}
AND r.member_id=#{q.filters.memberId}
AND r.status=#{q.filters.status}
AND r.financial_status=#{q.filters.financialStatus}
AND r.warehouse_id=#{q.filters.warehouseId}
AND r.currency=#{q.filters.currency}
AND r.created_at >= #{q.createdFrom} AND r.created_at < #{q.createdTo}

  ORDER BY r.created_at DESC,r.id DESC
  ORDER BY r.id ASC

LIMIT #{q.fetchLimit}
